#include <string.h>
#include <stdio.h>

void process_command(const char *input) {
    char buffer[32];
    strcpy(buffer, input);
    printf("Processing: %s\n", buffer);
}

int main(void) {
    char user_input[256];
    fgets(user_input, sizeof(user_input), stdin);
    process_command(user_input);
    return 0;
}
